// The Vite configuration of the NgDoc site "docs", generated by
// `ng g @ng-doc/builder:migrate-to-vite` from its legacy build target. The vite-application and
// vite-dev-server targets run it. Edit it freely; the schematic does not overwrite it.

import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { createNgDocAngularPlugins } from '@ng-doc/builder/generator/vite/angular/index.js';
import { createNgDocApplicationPlugin, createNgDocVitePlugin } from '@ng-doc/builder/generator/vite/index.js';

const workspaceRoot = fileURLToPath(new URL('./', import.meta.url));
/** A workspace-relative path as an absolute one. */
const workspace = (file) => path.join(workspaceRoot, file);
/**
 * The root of the repository. NgDoc resolves the API scopes of ng-doc.api.ts from it and builds the "edit" and
 * "view source" links of the pages from paths relative to it.
 */
const repositoryRoot = path.resolve(workspaceRoot, '../..');

/** The settings that differ between the build configurations, by Vite mode. */
const modes = { production: {}, development: { sourcemap: true } };
/** The settings of any other mode: the build target options without a configuration. */
const fallback = {};

export default ({ mode }) => {
  const settings = modes[mode] ?? fallback;
  return {
    root: workspace('src'),
    publicDir: false,
    server: { port: 4200 },
    plugins: [
      createNgDocApplicationPlugin({
        workspaceRoot,
        sourceRoot: 'src',
        browser: 'src/main.ts',
        // Turns on the server bundle and the prerender of every route in a build.
        server: 'src/main.server.ts',
        styles: [
          'src/styles.css',
          'node_modules/@ng-doc/app/styles/themes/dark.css',
          'node_modules/@ng-doc/app/styles/global.css',
        ],
        assets: [
          'src/favicon.ico',
          'src/favicon.svg',
          { glob: 'robots.txt', input: 'src/assets', output: '/' },
          'src/assets',
          {
            glob: '**/*',
            input: 'node_modules/@ng-doc/ui-kit/assets',
            output: 'assets/ng-doc/ui-kit',
          },
        ],
      }),
      createNgDocVitePlugin({
        analogLiveReload: true,
        angularPlugins: createNgDocAngularPlugins({
          tsconfig: workspace('tsconfig.app.json'),
          workspaceRoot,
          jit: false,
          disableTypeChecking: false,
          liveReload: true,
          inlineStylesExtension: 'scss',
        }),
        angularComponentProbe: workspace('src/app/app.component.ts'),
        generator: {
          projectId: 'docs',
          workspaceRoot: repositoryRoot,
          configFile: workspace('ng-doc.config.ts'),
          defaults: {
            docsRoot: workspace('src'),
            tsConfig: workspace('tsconfig.app.json'),
            outputRoot: workspace('ng-doc/docs'),
            cacheRoot: workspace('.cache/ng-doc/docs'),
          },
        },
      }),
    ],
    build: {
      outDir: workspace('../../dist/apps/docs/browser'),
      emptyOutDir: true,
      sourcemap: settings.sourcemap,
    },
  };
};
